      investTitle: "\u0633\u0648\u0642 \u0627\u0644\u0623\u0633\u0647\u0645 \u0648\u0627\u0644\u0639\u0642\u0627\u0631\u0627\u062A",
      investDesc: "\u062A\u0639\u0644\u0645 \u0627\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631 \u0628\u0644\u0627 \u0645\u062E\u0627\u0637\u0631. \u0627\u0634\u062A\u0631 \u0627\u0644\u0623\u0633\u0647\u0645\u060C \u0627\u0644\u0639\u0642\u0627\u0631\u0627\u062A \u0648\u0627\u0644\u0633\u0646\u062F\u0627\u062A \u0641\u064A \u0633\u0648\u0642 \u0645\u062D\u0627\u0643\u0627\u0629 \u064A\u062A\u0641\u0627\u0639\u0644 \u0645\u0639 \u0627\u0644\u0623\u062D\u062F\u0627\u062B \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0644\u062A\u0628\u0646\u064A \u062B\u0631\u0648\u062A\u0643.",
