      learningDesc: "\u0627\u0628\u062F\u0623 \u0628\u0627\u0644\u062F\u0631\u0648\u0633 \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629 \u0643\u0645\u062A\u062F\u0631\u0628\u060C \u0623\u0648 \u0627\u0641\u062A\u062D \u0627\u0644\u0645\u0646\u0647\u062C \u0627\u0644\u0645\u062A\u0642\u062F\u0645 \u0643\u0627\u0645\u0644\u0627\u064B \u0628\u0645\u0627 \u0641\u064A \u0630\u0644\u0643 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0648\u0627\u0644\u062A\u062C\u0627\u0631\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0643\u0645\u062A\u062F\u0631\u0628 \u062A\u0646\u0641\u064A\u0630\u064A (CEO).",
