      arcadeTitle: "\u0623\u0631\u0643\u064A\u062F \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0648\u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062C\u0627\u0646\u0628\u064A\u0629",
